import { experiments } from '@/data/experiments';
import { notFound } from 'next/navigation';
import { Divider, Tag } from '@/components/ui';
import Link from 'next/link';

export function generateStaticParams() {
  return experiments.map((exp) => ({
    slug: exp.slug,
  }));
}

export default async function ExperimentDetail({ params }: { params: Promise<{ slug: string }> }) {
  const resolvedParams = await params;
  const exp = experiments.find(e => e.slug === resolvedParams.slug);

  if (!exp) {
    notFound();
  }

  return (
    <main className="min-h-screen pt-48 pb-32 bg-ink text-canvas">
      <style>{`
        body { background-color: var(--color-ink); color: var(--color-canvas); }
      `}</style>

      <header className="px-6 md:px-12 max-w-5xl mx-auto mb-16">
        <Tag>{exp.id}</Tag>
        <h1 className="font-display text-5xl md:text-7xl font-medium tracking-tight mt-6 mb-6">{exp.title}</h1>
        <div className="flex flex-wrap gap-2">
          {exp.tags.map(tag => (
            <span key={tag} className="font-mono text-xs uppercase tracking-widest text-slate border border-slate/30 px-2 py-1 rounded">
              {tag}
            </span>
          ))}
        </div>
      </header>

      {/* Hero Media */}
      <div className="w-full h-[60vh] bg-white/5 mb-24 relative overflow-hidden flex items-center justify-center">
        {exp.media.src ? (
          <img src={exp.media.src} alt={exp.title} className="w-full h-full object-cover opacity-80" />
        ) : (
          <div className="font-mono text-slate text-sm">AWAITING_PROTOTYPE_MOUNT</div>
        )}
      </div>

      <div className="px-6 md:px-12 max-w-3xl mx-auto">
        <p className="font-sans text-xl md:text-3xl leading-snug">{exp.description}</p>
      </div>

      <Divider />

      <section className="px-6 md:px-12 max-w-3xl mx-auto">
        <Link href="/lab" className="font-mono text-sm uppercase tracking-widest hover:text-signal transition-colors">
          &larr; Back to Lab
        </Link>
      </section>
    </main>
  );
}
